css:
.authsim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #1a2233;
    background: linear-gradient(160deg, #f3f1ea 0%, #eceadf 100%);
    border-radius: 18px;
}

.authsim-container * {
    box-sizing: border-box;
}

.authsim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #11203d 0%, #1c3157 55%, #2a4a7a 100%);
    color: #f6f4ec;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 10px 30px rgba(17, 32, 61, 0.32);
    border-top: 4px solid #c9a227;
}

.authsim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
}

.authsim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #e8d28a;
    background: rgba(201, 162, 39, 0.16);
    padding: 5px 14px;
    border-radius: 999px;
}

.authsim-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #dde6f3;
}

.authsim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #24385c;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.authsim-period-counter #currentDay,
.authsim-period-counter #maxPeriods {
    font-weight: 800;
    color: #11203d;
}

.authsim-round-name {
    background: #dfe6f2;
    color: #11203d;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.authsim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #8a5a12;
    background: #f7ecd0;
    padding: 4px 12px;
    border-radius: 999px;
}

.authsim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.authsim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #e0ddd0;
    box-shadow: 0 4px 14px rgba(17, 32, 61, 0.06);
    border-top: 4px solid #2a4a7a;
}

.authsim-card-adoption { border-top-color: #1f7a52; }
.authsim-card-trust { border-top-color: #2a4a7a; }
.authsim-card-ei { border-top-color: #7a4fb0; }
.authsim-card-resistance { border-top-color: #b0521f; }

.authsim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #6b7384;
}

.authsim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #11203d;
}

.authsim-card-adoption .authsim-value { color: #1f7a52; }
.authsim-card-trust .authsim-value { color: #2a4a7a; }
.authsim-card-ei .authsim-value { color: #7a4fb0; }
.authsim-card-resistance .authsim-value { color: #b0521f; }

.authsim-sublabel {
    font-size: 0.76rem;
    color: #7c8494;
    line-height: 1.35;
}

/* Trust crossing the 55 floor — the promise breaks. */
.authsim-trust-broken { border-top-color: #c0392b; }
.authsim-trust-broken .authsim-value { color: #c0392b; }
.authsim-trust-strong { border-top-color: #1f7a52; }
.authsim-trust-strong .authsim-value { color: #1f7a52; }

/* Resistance: green when low (good), red when high (bad). */
.authsim-resistance-low { border-top-color: #1f7a52; }
.authsim-resistance-low .authsim-value { color: #1f7a52; }
.authsim-resistance-high { border-top-color: #c0392b; }
.authsim-resistance-high .authsim-value { color: #c0392b; }

.authsim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #11203d;
    color: #eef2f9;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
    border-left: 4px solid #c9a227;
}

.authsim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #e8d28a;
}

.authsim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #2a4a7a;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(17, 32, 61, 0.05);
}

.authsim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.authsim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #11203d;
    margin-bottom: 6px;
}

.authsim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #2c3a52;
}

.authsim-briefing-text strong { color: #1f7a52; }
.authsim-briefing-text em { color: #b0521f; font-style: italic; }

.authsim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #e0ddd0;
    box-shadow: 0 4px 14px rgba(17, 32, 61, 0.06);
}

.authsim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #11203d;
    border-bottom: 2px solid #ece9dd;
    padding-bottom: 8px;
}

.authsim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #22324d;
    margin: 14px 0 6px;
}

.authsim-container select,
.authsim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #c8c3b0;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #fbfaf5;
    color: #1a2233;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.authsim-container select:focus,
.authsim-container input[type="number"]:focus {
    outline: none;
    border-color: #2a4a7a;
    box-shadow: 0 0 0 3px rgba(42, 74, 122, 0.15);
}

.authsim-container select option {
    background-color: #ffffff;
    color: #1a2233;
}

.authsim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #2a4a7a;
}

.authsim-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #24385c;
    margin-top: 4px;
}

.authsim-range-readout span:last-child {
    color: #1f7a52;
    font-weight: 800;
}

.authsim-hint {
    font-size: 0.8rem;
    color: #7c8494;
    margin-top: 4px;
    line-height: 1.4;
}

.authsim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.authsim-container .btn-primary {
    background: linear-gradient(135deg, #11203d 0%, #2a4a7a 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 6px 16px rgba(17, 32, 61, 0.28);
    color: #f6f4ec;
}

.authsim-container .btn-primary:hover {
    filter: brightness(1.12);
}

.authsim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #c8c3b0;
    color: #6b7384;
}

.authsim-coach {
    background: #11203d;
    color: #eef2f9;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(17, 32, 61, 0.24);
    border-left: 4px solid #c9a227;
}

.authsim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #e8d28a;
    margin-bottom: 8px;
}

.authsim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.authsim-coach-body strong { color: #f0d98c; }
.authsim-coach-body em { color: #f0b58c; font-style: italic; }

.authsim-history,
.authsim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #e0ddd0;
    box-shadow: 0 4px 14px rgba(17, 32, 61, 0.06);
}

.authsim-history h3,
.authsim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #11203d;
}

.authsim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #22324d;
}

.authsim-container table#usfHistoryTable th {
    background: #eef1f7;
    color: #11203d;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #d6dbe6;
}

.authsim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #eef0f4;
}

.authsim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f8f9fc;
}

.authsim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .authsim-container {
        padding: 14px;
    }
    .authsim-header h1 {
        font-size: 1.7rem;
    }
    .authsim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .authsim-value {
        font-size: 2rem;
    }
    .authsim-clock {
        margin-left: 0;
    }
    .authsim-period-counter {
        font-size: 0.88rem;
    }
    .authsim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .authsim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ---- v1.1.0 completion / debrief screen (light theme, authsim) ---- */
.authsim-completion { padding: 8px 4px 4px; }
.authsim-cm-head { text-align: center; margin-bottom: 16px; }
.authsim-cm-score { font-size: 3.2rem; font-weight: 800; line-height: 1; color: #1f7a52; }
.authsim-cm-score-max { font-size: 1.2rem; font-weight: 600; color: #5b9b7d; }
.authsim-cm-grade { font-size: 1.2rem; font-weight: 700; margin-top: 6px; color: #11203b; }
.authsim-cm-badge { display: inline-block; margin-left: 6px; padding: 2px 10px; border-radius: 999px; font-size: 0.78rem; font-weight: 700; vertical-align: middle; }
.authsim-cm-yes { background: rgba(31,122,82,0.14); color: #1a7059; border: 1px solid rgba(31,122,82,0.5); }
.authsim-cm-no { background: rgba(176,82,31,0.12); color: #b0521f; border: 1px solid rgba(176,82,31,0.45); }
.authsim-cm-metrics { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin: 12px 0 16px; }
.authsim-cm-metric { flex: 1 1 110px; min-width: 100px; background: rgba(42,74,122,0.08); border: 1px solid rgba(42,74,122,0.22); border-radius: 10px; padding: 10px 8px; text-align: center; }
.authsim-cm-mv { display: block; font-size: 1.4rem; font-weight: 800; color: #2a4a7a; }
.authsim-cm-ml { display: block; font-size: 0.72rem; margin-top: 4px; color: #5a6577; text-transform: uppercase; letter-spacing: 0.03em; }
.authsim-cm-insights-title { font-weight: 700; margin: 8px 0 6px; color: #11203b; }
.authsim-cm-insights { margin: 0; padding-left: 20px; }
.authsim-cm-insights li { margin-bottom: 8px; line-height: 1.5; font-size: 0.92rem; color: #2b3547; }

